window.AUTH=window.AUTH||{};window.AUTH["22-859"]={"d":"22-859","id":"2023/22-859","n":"Securities and Exchange Commission v. Jarkesy","briefs":[{"k":"petitioner","label":"Brief of petitioner Securites and Exchange Commission","date":"2023-08-28","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/278330/20230828183013049_22-859tsUnitedStates.pdf","side":"pet","n":160},{"k":"respondent","label":"Brief of respondents George R. Jarkesy, Jr., et al.","date":"2023-10-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/284699/20231011140507326_22-859%20Respondents%20Brief.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner Securites and Exchange Commission","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/289467/20231113164043876_22-859%20SEC%20v.%20Jarkesy.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r50_7kh7.pdf","tr":true,"items":[{"t":"case","label":"A. L. A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Abrams v. SSA","cite":"703 F.3d 538","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/703/538/","by":{"0":"60","2":"24"}},{"t":"case","label":"Andrews v. King","cite":"77 Me. 224","y":1885,"url":"https://www.courtlistener.com/c/Me./77/224/","op":1,"by":{"0":"64"}},{"t":"case","label":"Atlas Roofing Co. v. Occupational Safety & Health Review Comm’n","cite":"430 U.S. 442","y":1977,"id":"1976/75-746","sc":1,"op":119,"ar":61,"sum":"The Seventh Amendment does not prevent Congress from assigning to an administrative agency the task of adjudicating violations of OSHA. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 18, 19, 21-25, 28, 31, 44","1":"27, 32-34, 37-38, 45-46","2":"3, 6-10"}},{"t":"case","label":"Baldwin v. New York","cite":"399 U.S. 66","y":1970,"id":"1969/188","sc":1,"sum":"The judgment is reversed. Pp. 6776. 24 N. Y. 2d 207, 247 N. E. 2d 260, reversed. MR. JUSTICE WHITE, joined by MR. JUSTICE BRENNAN and MR. JUSTICE MARSHALL, concluded that defendants accused of serious crimes must, under the Sixth Amendment, as made applicable to the States by the Fourteenth Amendment, be afforded the right to trial by jury, Duncan v. Louisiana, 391 U. S. 145, and though \"petty crimes\" may be tried …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Biggs v. McBride","cite":"21 P. 878","y":1889,"court":"Or.","url":"https://www.courtlistener.com/c/P./21/878/","by":{"0":"64"}},{"t":"case","label":"Block v. Hirsh","cite":"256 U.S. 135","y":1921,"id":"scdb/1920-112","sc":1,"sum":"(1) That the legislative declaration of facts affording the ground for the regulation was entitled to great respect and was confirmed. by common knowledge.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20, 28"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"0":"53, 54, 66","1":"67","2":"27"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"op":1,"ar":2,"sum":"Explaining that agency rulemaking and adjudications may “take `legislative' and `judicial' forms, but they are exercises of—indeed, under our constitutional structure they must be exercises of—the `executive Power' ” (quoting Art. II, § 1, cl. 1).","sumSrc":"opinion","by":{"0":"37","1":"57, 59","2":"4"}},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"op":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"67","1":"53, 55, 65-66, 72","2":"24, 26, 29, 30"}},{"t":"case","label":"Commodity Futures Trading Comm’n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"op":5,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"39-40, 44","2":"7"}},{"t":"case","label":"Commonwealth v. Slifer","cite":"25 Pa. 23","y":1855,"url":"https://www.courtlistener.com/c/Pa./25/23/","by":{"0":"64"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"op":12,"ar":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 28","1":"40, 50","2":"16"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"51"}},{"t":"case","label":"Dullam v. Willson","cite":"19 N.W. 112","y":1884,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./19/112/","by":{"0":"64"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"sum":"The Court held that the judicial appointments were valid. The Court unanimously found that Congress has authorized the Secretary to appoint civilian members of the Coast Guard Court of Criminal Appeals.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"op":2,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 31"}},{"t":"case","label":"Flaherty & Crumrine Preferred Income Fund, Inc. v. TXU Corp.","cite":"565 F.3d 200","y":2009,"url":"https://www.courtlistener.com/c/F.3d/565/200/","by":{"0":"30"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":2,"sum":"Holding “that the dual for-cause limitations on the removal of [Public Company Accounting Oversight] Board members contravene the Constitution's separation of powers”.","sumSrc":"opinion","by":{"0":"54","1":"45, 52-55, 57,59, 62, 68"}},{"t":"case","label":"Granfinanciera, S. A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"op":44,"ar":24,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"0":"9, 20, 26-28","1":"26, 29, 40-43, 45","2":"7, 8"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15, 36, 37","1":"49"}},{"t":"case","label":"Ham v. Board of Police","cite":"7 N.E. 540","y":1886,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./7/540/","by":{"0":"64"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"15, 34-36","2":"15"}},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"op":4,"ar":2,"sum":"That an acquittal of a charge of wilful attempt to evade, under § 146 (b), does not bar assessment and collection of the 50% addition prescribed by § 293 (b)..397 et seq. The doctrine of res judicata is inapplicable because of the difference in quantum of proof in civil and criminal cases; the acquittal was merely an adjudication that the proof was not sufficient to overcome all reasonable doubt of guilt. P. 397. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"HHS v. Jarboe","cite":"2023 M.S.P.B. 22","y":2023,"court":"Aug. 2","url":"https://www.courtlistener.com/c/M.S.P.B./2023/22/","by":{"0":"60, 63","2":"21"}},{"t":"case","label":"Hughes v. SEC","cite":"174 F.2d 969","y":1949,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/174/969/","by":{"0":"30"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"62","1":"55-56, 58"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"9, 40-43","1":"61"}},{"t":"case","label":"Kokesh v. SEC","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"op":1,"ar":2,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"24","2":"9"}},{"t":"case","label":"Lloyd Sabaudo Societa Anonima Per Azioni v. Elting","cite":"287 U.S. 329","y":1932,"id":"scdb/1932-015","sc":1,"op":2,"by":{"0":"23"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"0":"7, 49, 58","1":"52, 57, 65, 71-72","2":"22, 29"}},{"t":"case","label":"Lynch v. Chase","cite":"40 P. 666","y":1895,"court":"Kan.","url":"https://www.courtlistener.com/c/P./40/666/","by":{"0":"64"}},{"t":"case","label":"Marshall Field v. Clark","cite":"143 U.S. 649","y":1892,"id":"scdb/1891-139","sc":1,"sum":"The signing by the Speaker of the House of Representatives and by the President of the Senate, in open session, of an enrolled bill, is an official attestation by the two Houses of such bill as one that has passed Congress; and when the bill thus attested receives the approval of the President, and is deposited in the Department of State according to law, its authentication as a bill that has passed Congress is …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37","1":"48-49","2":"17"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"36, 37","1":"49","2":"17"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"0":"47, 50, 60-62","1":"56, 58","2":"18, 19, 21"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"46, 47, 50, 55","1":"55, 60-61","2":"18, 19, 24, 26"}},{"t":"case","label":"N. Sims Organ & Co. v. SEC","cite":"293 F.2d 78","y":1961,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/293/78/","by":{"0":"30"}},{"t":"case","label":"NLRB v. Jones & Laughlin Steel Corp.","cite":"301 U.S. 1","y":1937,"id":"1900-1940/301us1","sc":1,"op":3,"sum":"The Court found that the Commerce Clause gave the government the right to regulate labor-management disputes.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"65","2":"13"}},{"t":"case","label":"North Am. Co. v. SEC","cite":"327 U.S. 686","y":1946,"id":"scdb/1945-064","sc":1,"op":1,"sum":"1. The enactment of § 11 (b) (1) of the Public Utility Holding Company Act of 1935, authorizing the Securities and Exchange Commission to require each public utility holding company engaged in interstate commerce to limit its operations to a single integrated public utility system, was within the power of Congress under the commerce clause of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"op":11,"ar":1,"sum":"Money paid to the collector of a port under protest, and on the certainty that if not paid clearance to vessels necessarily sailing on definite schedule would be refused, to the great damage of the owner, is paid involuntarily,'and can, if unlawfully exacted, be recovered;","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23","1":"50","2":"7, 13, 16"}},{"t":"case","label":"Oil States Energy Servs., LLC v. Greene’s Energy Grp., LLC","cite":"138 S. Ct. 1365","y":2018,"id":"2017/16-712","sc":1,"op":10,"sum":"The Court decided that inter partes review, which authorizes the United States Patent and Trademark Office to reconsider and cancel an already-issued patent claim under 35 U.S.C. §§ 311-391, does not violate Article III or the Seventh Amendment of the Constitution.","sumSrc":"Oyez","by":{"0":"13, 18, 20, 21, 32, 33","1":"28, 43-44, 46","2":"4, 5, 11"}},{"t":"case","label":"Panama Ref. Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"sum":"Writing for the 8-1 majority, Chief Justice Charles E. Hughes concluded the order was not constitutional. Supreme Court held that in enacting the order, the President subsumed legislative powers that Congress does not have the power to delegate. Congress cannot delegate legislative powers to other branches of government in order to sustain the democratic system of government.","sumSrc":"Oyez","by":{"0":"36, 37"}},{"t":"case","label":"Passavant v. United States","cite":"148 U.S. 214","y":1893,"id":"scdb/1892-141","sc":1,"op":1,"ar":1,"sum":"The act of June 10, 1890, “ to simplify the laws in relation to the collection of the revenue,” 26 Stat. 131, c. 407, confers no jurisdiction upon Circuit Courts of the United States, on.the application of dissatisfied importers, to review and reverse a decision of a board of general appraisers ascertaining and fixing the dutiable value of imported goods, when such board has acted in pursuance of law, and without …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"People ex rel. Mayor v. Nichols","cite":"79 N.Y. 582","y":1880,"url":"https://www.courtlistener.com/c/N.Y./79/582/","by":{"0":"64"}},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"op":1,"sum":"The Court affirmed the Fifth Circuit and held that Sindermann was entitled to a full trial in federal District Court and a hearing before the Board of Regents. The Court acknowledged that Sindermann did not have a contractual or tenure-based right to continued employment by Odessa Junior College.","sumSrc":"Oyez","by":{"0":"63"}},{"t":"case","label":"Ramspeck v. Federal Trial Exam’rs Conference","cite":"345 U.S. 128","y":1953,"id":"scdb/1952-062","sc":1,"sum":"Certain -provisions of regulations promulgated by the Civil Service Commission under § 11 of the Administrative Procedure Act and governing the classification, promotion, compensation fnd tenure of trial examiners and the assignment of cases to them are here sustained as conforming to the statute and carrying out the purpose and intent of Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53, 60, 66","1":"68","2":"26, 27"}},{"t":"case","label":"Reagan v. United States","cite":"182 U.S. 419","y":1901,"id":"scdb/1900-066","sc":1,"sum":"In 1896, commissioners appointed by judges of the United States Court in the Indian Territory were inferior officers, not holding their offices for life, or by any fixed tenure, but subject to removal by the appointing power.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"63"}},{"t":"case","label":"SEC v. Blavin","cite":"760 F.2d 706","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/706/","op":3,"sum":"Explaining that, in contrast to the common law of fraud, federal securities laws do not require proof “that any investor actually relied on [a party’s] misrepresentations or that the misrepresentations caused any investor to lose money”.","sumSrc":"brief:0","by":{"0":"25, 30"}},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"op":3,"by":{"0":"3, 31","1":"36-37"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":2,"ar":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"47, 50, 51","1":"52, 54-59","2":"19, 26, 28"}},{"t":"case","label":"Shurtleff v. United States","cite":"189 U.S. 311","y":1903,"id":"scdb/1902-126","sc":1,"sum":"Where Congress creates an office and provides for the removal of the incumbent at any time for inefficiency, neglect of duty, or malfeasance in office, if the removal of the officer is sought to be made for any of those causes he is entitled to notice and a hearing; but if the President removes him without giving him notice and an opportunity to defend himself, it must be presumed that the removal was not made for …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"63, 64"}},{"t":"case","label":"SSA v. Burris","cite":"39 M.S.P.R. 51","y":1988,"url":"https://www.courtlistener.com/c/M.S.P.R./39/51/","by":{"0":"60"}},{"t":"case","label":"SSA v. Goodman","cite":"19 M.S.P.R. 321","y":1984,"url":"https://www.courtlistener.com/c/M.S.P.R./19/321/","by":{"0":"60","1":"63"}},{"t":"case","label":"SSA v. Levinson","cite":"2023 M.S.P.B. 20","y":2023,"court":"July 12","url":"https://www.courtlistener.com/c/M.S.P.B./2023/20/","op":1,"by":{"0":"63","2":"22"}},{"t":"case","label":"SSA v. Long","cite":"113 M.S.P.R. 190","y":2010,"url":"https://www.courtlistener.com/c/M.S.P.R./113/190/","by":{"0":"60"}},{"t":"case","label":"SSA v. Mills","cite":"73 M.S.P.R. 463","y":1996,"url":"https://www.courtlistener.com/c/M.S.P.R./73/463/","op":1,"by":{"0":"60"}},{"t":"case","label":"SSA v. Steverson","cite":"111 M.S.P.R. 649","y":2009,"url":"https://www.courtlistener.com/c/M.S.P.R./111/649/","by":{"0":"60"}},{"t":"case","label":"State ex rel. Attorney Gen. v. Hawkins","cite":"5 N.E. 228","y":1886,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./5/228/","by":{"0":"64"}},{"t":"case","label":"State ex rel. Hart v. Common Council","cite":"55 N.W. 118","y":1893,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./55/118/","op":1,"by":{"0":"64"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"op":16,"ar":6,"sum":"Describing Commodity Futures Trading Comm'n v. Schor, 478 U. S. 833 (1986).","sumSrc":"opinion","by":{"0":"18","1":"28, 32, 43, 65"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Scientific-Atlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"op":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"op":29,"ar":12,"sum":"The Clean Water Act (Act) authorizes injunctive relief against violators (33 U. S. C. § 1319(b)) and subjects them to a civil penalty not to exceed $10,000 per day (§ 1319(d)). After denying petitioner's timely demand for a jury trial in the Government's suit for relief under §§ 1319(b) and 1319(d), the District Court imposed civil penalties and granted injunctive relief against petitioner. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 19, 28, 29","1":"12, 30","2":"4, 5, 12"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"141 S. Ct. 1970","y":2021,"id":"2020/19-1434","sc":1,"op":2,"ar":1,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"54, 56, 58, 59","2":"20, 25, 28"}},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"sum":"A defendant convicted of violating § 922 (h) is properly sentenced under § 924 (a) even though his conduct also violates § 1202 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 35, 38, 39, 43","2":"16"}},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"op":1,"sum":"1. Civil surgeons appointed by the Commissioner of Pensions under sect. 4777 of the Revised Statutes are not officers of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"United States v. Gordon","cite":"548 F.2d 743","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/548/743/","by":{"0":"44"}},{"t":"case","label":"United States v. Grimaud","cite":"220 U.S. 506","y":1911,"id":"scdb/1910-122","sc":1,"sum":"Under the acts establishing forest reservations, their use for grazing or other lawful purposes is subject to rules and regulations established by the Secretary of Agriculture, and it being impracticable for Congress to provide general regulations, that body acted within its constitutional power in conferring power on the Secretary to establish such rules; the power so conferred being administrative and not …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37","2":"17"}},{"t":"case","label":"United States v. LaSalle Nat’l Bank","cite":"437 U.S. 298","y":1978,"id":"1977/77-365","sc":1,"sum":"The District Court erred in refusing to enforce the summonses, since its finding that the agent was investigating the taxpayer \"solely for the purpose of unearthing evidence of criminal conduct\" does not necessarily lead to the conclusion that the summonses were not issued in good-faith pursuit of the congressionally authorized purposes of § 7602.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"sum":"When Congress by law, vests the appointment of inferior officers in the heads of departments, it may limit and restrict the power of removal as it deems best for the public interests.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"34, 51","1":"56, 58","2":"18"}},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"sum":"The National Labor Relations Board ordered petitioner to reinstate with back pay an employee found to have been discharged because he gave certain testimony in another proceeding under the National Labor Relations Act. The evidence as to the reason for his discharge was conflicting; and the Board overruled its examiner's findings of fact and his recommendation that the proceedings be dismissed. In decreeing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 58"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"34, 36, 37"}},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"sum":"The Court held that the President did not have the authority to remove individuals from the War Claims Commission at will.","sumSrc":"Oyez","by":{"0":"62"}},{"t":"case","label":"Withrow v. Larkin","cite":"421 U.S. 35","y":1975,"id":"1974/73-1573","sc":1,"sum":"Wisconsin statutes prohibit various acts of professional misconduct by physicians and empower a State Examining Board to warn and reprimand physicians, to temporarily suspend licenses, and to institute criminal action or action to revoke a license. When the Board notified appellee licensed physician that a closed investigative hearing, which appellee and his attorney could attend, would be held to determine whether …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53"}},{"t":"case","label":"Wong Yang Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"sum":"This was contrary to the purpose of the Administrative Procedure Act to ameliorate the evils resulting from a combination of the prosecuting and adjudicating functions in administrative proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53, 66"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"8, 10, 12, 16, 34, 45, 47-50, 55-57, 65"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"0":"4","2":"3"}},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","subs":["(a)","(b)","(c)"],"by":{"0":"57, 5, 5, 57"}},{"t":"usc","label":"5 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/5/557","subs":["(b)"],"by":{"0":"5, 45, 58"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)"],"by":{"0":"35"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"28"}},{"t":"law","label":"Pub. L. No. 98-376","url":"https://www.govinfo.gov/link/statute/98/1264","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","by":{"0":"2, 24","1":"3"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","subs":["(4)"],"by":{"0":"30","1":"4, 36"}},{"t":"usc","label":"15 U.S.C. § 80b-9","url":"https://www.law.cornell.edu/uscode/text/15/80b-9","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 651","url":"https://www.law.cornell.edu/uscode/text/29/651","stext":{"head":"§651. Congressional statement of findings and declaration of purpose and policy","paras":[[0,"(a) The Congress finds that personal injuries and illnesses arising out of work situations impose a substantial burden upon, and are a hindrance to, interstate commerce in terms of lost production, wage loss, medical expenses, and disability compensation payments."],[0,"(b) The Congress declares it to be its purpose and policy, through the exercise of its powers to regulate commerce among the several States and with foreign nations and to provide for the general welfare, to assure so far as possible every working man and woman in the Nation safe and healthful working conditions and to preserve our human resources—"],[1,"(1) by encouraging employers and employees in their efforts to reduce the number of occupational safety and health hazards at their places of employment, and to stimulate employers and employees to institute new and to perfect existing programs for providing safe and healthful working conditions;"],[1,"(2) by providing that employers and employees have separate but dependent responsibilities and rights with respect to achieving safe and healthful working conditions;"],[1,"(3) by authorizing the Secretary of Labor to set mandatory occupational safety and health standards applicable to businesses affecting interstate commerce, and by creating an Occupational Safety and Health Review Commission for carrying out adjudicatory functions under this chapter;"],[1,"(4) by building upon advances already made through employer and employee initiative for providing safe and healthful working conditions;"],[1,"(5) by providing for research in the field of occupational safety and health, including the psychological factors involved, and by developing innovative methods, techniques, and approaches for dealing with occupational safety and health problems;"],[1,"(6) by exploring ways to discover latent diseases, establishing causal connections between diseases and work in environmental conditions, and conducting other research relating to health problems, in recognition of the fact that occupational health standards present problems often different from those involved in occupational safety;"],[1,"(7) by providing medical criteria which will assure insofar as practicable that no employee will suffer diminished health, functional capacity, or life expectancy as a result of his work experience;"],[1,"(8) by providing for training programs to increase the number and competence of personnel engaged in the field of occupational safety and health;"],[1,"(9) by providing for the development and promulgation of occupational safety and health standards;"],[1,"(10) by providing an effective enforcement program which shall include a prohibition against giving advance notice of any inspection and sanctions for any individual violating this prohibition;"],[1,"(11) by encouraging the States to assume the fullest responsibility for the administration and enforcement of their occupational safety and health laws by providing grants to the States to assist in identifying their needs and responsibilities in the area of occupational safety and health, to develop plans in accordance with the provisions of this chapter, to improve the administration and enforcement of State occupational safety and health laws, and to conduct experimental and demonstration projects in connection therewith;"],[1,"(12) by providing for appropriate reporting procedures with respect to occupational safety and health which procedures will help achieve the objectives of this chapter and accurately describe the nature of the occupational safety and health problem;"],[1,"(13) by encouraging joint labor-management efforts to reduce injuries and disease arising out of employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/651?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§651. Congressional statement of findings and declaration of purpose and policy","tname":"Labor","by":{"0":"21","2":"8"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","stext":{"head":"§77a. Short title","paras":[[0,"This subchapter may be cited as the \"Securities Act of 1933\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77a. Short title","tname":"Commerce and Trade","by":{"0":"2","1":"36, 3"}},{"t":"usc","label":"15 U.S.C. § 77h-1","url":"https://www.law.cornell.edu/uscode/text/15/77h-1","subs":["(g)"],"by":{"0":"30","2":"9, 9"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§77q. Fraudulent interstate transactions","tname":"Commerce and Trade","by":{"0":"30","1":"4"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","stext":{"head":"§77t. Injunctions and prosecution of offenses","paras":[[0,"(a) Investigation of violations"],[0,"Whenever it shall appear to the Commission, either upon complaint or otherwise, that the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, have been or are about to be violated, it may, in its discretion, either require or permit such person to file with it a statement in writing, under oath, or otherwise, as to all the facts and circumstances concerning the subject matter which it believes to be in the public interest to investigate, and may investigate such facts."],[0,"(b) Action for injunction or criminal prosecution in district court"],[0,"Whenever it shall appear to the Commission that any person is engaged or about to engage in any acts or practices which constitute or will constitute a violation of the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, the Commission may, in its discretion, bring an action in any district court of the United States, or United States court of any Territory, to enjoin such acts or practices, and upon a proper showing, a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices to the Attorney General who may, in his discretion, institute the necessary criminal proceedings under this subchapter. Any such criminal proceeding may be brought either in the district wherein the transmittal of the prospectus or security complained of begins, or in the district wherein such prospectus or security is received."],[0,"(c) Writ of mandamus"],[0,"Upon application of the Commission, the district courts of the United States and the United States courts of any Territory shall have jurisdiction to issue writs of mandamus commanding any person to comply with the provisions of this subchapter or any order of the Commission made in pursuance thereof."],[0,"(d) Money penalties in civil actions"],[0,"(1) Authority of Commission"],[1,"Whenever it shall appear to the Commission that any person has violated any provision of this subchapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation."],[0,"(2) Amount of penalty"],[0,"(A) First tier"],[2,"The amount of the penalty shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (i) $5,000 for a natural person or $50,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation."],[0,"(B) Second tier"],[2,"Notwithstanding subparagraph (A), the amount of penalty for each such violation shall not exceed the greater of (i) $50,000 for a natural person or $250,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(C) Third tier"],[2,"Notwithstanding subparagraphs (A) and (B), the amount of penalty for each such violation shall not exceed the greater of (i) $100,000 for a natural person or $500,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"],[3,"(I) the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[3,"(II) such violation directly or indirectly resulted in substantial losses or created a significant risk of substantial losses to other persons."],[0,"(3) Procedures for collection"],[0,"(A) Payment of penalty to Treasury"],[2,"A penalty imposed under this section shall be payable into the Treasury of the United States, except as otherwise provided in section 7246 of this title and section 78u–6 of this title."],[0,"(B) Collection of penalties"],[2,"If a person upon whom such a penalty is imposed shall fail to pay such penalty within the time prescribed in the court's order, the Commission may refer the matter to the Attorney General who shall recover such penalty by action in the appropriate United States district court."],[0,"(C) Remedy not exclusive"],[2,"The actions authorized by this subsection may be brought in addition to any other action that the Commission or the Attorney General is entitled to bring."],[0,"(D) Jurisdiction and venue"],[2,"For purposes of section 77v of this title, actions under this section shall be actions to enforce a liability or a duty created by this subchapter."],[0,"(4) Special provisions relating to a violation of a cease-and-desist order"],[1,"In an action to enforce a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, each separate violation of such order shall be a separate offense, except that in the case of a violation through a continuing failure to comply with such an order, each day of the failure to comply with the order shall be deemed a separate offense."],[0,"(e) Authority of court to prohibit persons from serving as officers and directors"],[0,"In any proceeding under subsection (b), the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 77q(a)(1) of this title from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(f) Prohibition of attorneys' fees paid from Commission disgorgement funds"],[0,"Except as otherwise ordered by the court upon motion by the Commission, or, in the case of an administrative action, as otherwise ordered by the Commission, funds disgorged as the result of an action brought by the Commission in Federal court, or as a result of any Commission administrative action, shall not be distributed as payment for attorneys' fees or expenses incurred by private parties seeking distribution of the disgorged funds."],[0,"(g) Authority of a court to prohibit persons from participating in an offering of penny stock"],[0,"(1) In general"],[1,"In any proceeding under subsection (a) against any person participating in, or, at the time of the alleged misconduct, who was participating in, an offering of penny stock, the court may prohibit that person from participating in an offering of penny stock, conditionally or unconditionally, and permanently or for such period of time as the court shall determine."],[0,"(2) Definition"],[1,"For purposes of this subsection, the term \"person participating in an offering of penny stock\" includes any person engaging in activities with a broker, dealer, or issuer for purposes of issuing, trading, or inducing or attempting to induce the purchase or sale of, any penny stock. The Commission may, by rule or regulation, define such term to include other activities, and may, by rule, regulation, or order, exempt any person or class of persons, in whole or in part, conditionally or unconditionally, from inclusion in such term."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77t?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§77t. Injunctions and prosecution of offenses","tname":"Commerce and Trade","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"0":"2","1":"3"}},{"t":"usc","label":"15 U.S.C. § 78b","url":"https://www.law.cornell.edu/uscode/text/15/78b","by":{"0":"3, 24, 30"}},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","subs":["(a)"],"stext":{"head":"§78d. Securities and Exchange Commission","paras":[[0,"(a) Establishment; composition; limitations on commissioners; terms of office"],[0,"There is hereby established a Securities and Exchange Commission (hereinafter referred to as the \"Commission\") to be composed of five commissioners to be appointed by the President by and with the advice and consent of the Senate. Not more than three of such commissioners shall be members of the same political party, and in making appointments members of different political parties shall be appointed alternately as nearly as may be practicable. No commissioner shall engage in any other business, vocation, or employment than that of serving as commissioner, nor shall any commissioner participate, directly or indirectly, in any stock-market operations or transactions of a character subject to regulation by the Commission pursuant to this chapter. Each commissioner shall hold office for a term of five years and until his successor is appointed and has qualified, except that he shall not so continue to serve beyond the expiration of the next session of Congress subsequent to the expiration of said fixed term of office, and except (1) any commissioner appointed to fill a vacancy occurring prior to the expiration of the term for which his predecessor was appointed shall be appointed for the remainder of such term, and (2) the terms of office of the commissioners first taking office after June 6, 1934, shall expire as designated by the President at the time of nomination, one at the end of one year, one at the end of two years, one at the end of three years, one at the end of four years, and one at the end of five years, after June 6, 1934."],[0,"(b) Appointment and compensation of staff and leasing authority"],[0,"(1) Appointment and compensation"],[1,"The Commission shall appoint and compensate officers, attorneys, economists, examiners, and other employees in accordance with section 4802 of title 5."],[0,"(2) Reporting of information"],[1,"In establishing and adjusting schedules of compensation and benefits for officers, attorneys, economists, examiners, and other employees of the Commission under applicable provisions of law, the Commission shall inform the heads of the agencies referred to under section 1833b of title 12 and Congress of such compensation and benefits and shall seek to maintain comparability with such agencies regarding compensation and benefits."],[0,"(3) Leasing authority"],[1,"Nothwithstanding 1 any other provision of law, the Commission is authorized to enter directly into leases for real property for office, meeting, storage, and such other space as is necessary to carry out its functions, and shall be exempt from any General Services Administration space management regulations or directives."],[0,"(c) Acceptance of travel support for Commission activities from non-Federal sources; regulations"],[0,"Notwithstanding any other provision of law, in accordance with regulations which the Commission shall prescribe to prevent conflicts of interest, the Commission may accept payment and reimbursement, in cash or in kind, from non-Federal agencies, organizations, and individuals for travel, subsistence, and other necessary expenses incurred by Commission members and employees in attending meetings and conferences concerning the functions or activities of the Commission. Any payment or reimbursement accepted shall be credited to the appropriated funds of the Commission. The amount of travel, subsistence, and other necessary expenses for members and employees paid or reimbursed under this subsection may exceed per diem amounts established in official travel regulations, but the Commission may include in its regulations under this subsection a limitation on such amounts."],[0,"(d) Acceptance of relocation expenses from former employers by professional fellows program participants"],[0,"Notwithstanding any other provision of law, former employers of participants in the Commission's professional fellows programs may pay such participants their actual expenses for relocation to Washington, District of Columbia, to facilitate their participation in such programs, and program participants may accept such payments."],[0,"(e) Fee payments"],[0,"Notwithstanding any other provision of law, whenever any fee is required to be paid to the Commission pursuant to any provision of the securities laws or any other law, the Commission may provide by rule that such fee shall be paid in a manner other than in cash and the Commission may also specify the time that such fee shall be determined and paid relative to the filing of any statement or document with the Commission."],[0,"(f) Reimbursement of expenses for assisting foreign securities authorities"],[0,"Notwithstanding any other provision of law, the Commission may accept payment and reimbursement, in cash or in kind, from a foreign securities authority, or made on behalf of such authority, for necessary expenses incurred by the Commission, its members, and employees in carrying out any investigation pursuant to section 78u(a)(2) of this title or in providing any other assistance to a foreign securities authority. Any payment or reimbursement accepted shall be considered a reimbursement to the appropriated funds of the Commission."],[0,"(g) Office of the Investor Advocate"],[0,"(1) Office established"],[1,"There is established within the Commission the Office of the Investor Advocate (in this subsection referred to as the \"Office\")."],[0,"(2) Investor Advocate"],[0,"(A) In general"],[2,"The head of the Office shall be the Investor Advocate, who shall—"],[3,"(i) report directly to the Chairman; and"],[3,"(ii) be appointed by the Chairman, in consultation with the Commission, from among individuals having experience in advocating for the interests of investors in securities and investor protection issues, from the perspective of investors."],[0,"(B) Compensation"],[2,"The annual rate of pay for the Investor Advocate shall be equal to the highest rate of annual pay for other senior executives who report to the Chairman of the Commission."],[0,"(C) Limitation on service"],[2,"An individual who serves as the Investor Advocate may not be employed by the Commission—"],[3,"(i) during the 2-year period ending on the date of appointment as Investor Advocate; or"],[3,"(ii) during the 5-year period beginning on the date on which the person ceases to serve as the Investor Advocate."],[0,"(3) Staff of Office"],[1,"The Investor Advocate, after consultation with the Chairman of the Commission, may retain or employ independent counsel, research staff, and service staff, as the Investor Advocate deems necessary to carry out the functions, powers, and duties of the Office."],[0,"(4) Functions of the Investor Advocate"],[1,"The Investor Advocate shall—"],[2,"(A) assist retail investors in resolving significant problems such investors may have with the Commission or with self-regulatory organizations;"],[2,"(B) identify areas in which investors would benefit from changes in the regulations of the Commission or the rules of self-regulatory organizations;"],[2,"(C) identify problems that investors have with financial service providers and investment products;"],[2,"(D) analyze the potential impact on investors of—"],[3,"(i) proposed regulations of the Commission; and"],[3,"(ii) proposed rules of self-regulatory organizations registered under this chapter; and"],[2,"(E) to the extent practicable, propose to the Commission changes in the regulations or orders of the Commission and to Congress any legislative, administrative, or personnel changes that may be appropriate to mitigate problems identified under this paragraph and to promote the interests of investors."],[0,"(5) Access to documents"],[1,"The Commission shall ensure that the Investor Advocate has full access to the documents of the Commission and any self-regulatory organization, as necessary to carry out the functions of the Office."],[0,"(6) Annual reports"],[0,"(A) Report on objectives"],[0,"(i) In general"],[3,"Not later than June 30 of each year after 2010, the Investor Advocate shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate and the Committee on Financial Services of the House of Representatives a report on the objectives of the Investor Advocate for the following fiscal year."],[0,"(ii) Contents"],[3,"Each report required under clause (i) shall contain full and substantive analysis and explanation."],[0,"(B) Report on activities"],[0,"(i) In general"],[3,"Not later than December 31 of each year after 2010, the Investor Advocate shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate and the Committee on Financial Services of the House of Representatives a report on the activities of the Investor Advocate during the immediately preceding fiscal year."],[0,"(ii) Contents"],[3,"Each report required under clause (i) shall include—"],[4,"(I) appropriate statistical information and full and substantive analysis;"],[4,"(II) information on steps that the Investor Advocate has taken during the reporting period to improve investor services and the responsiveness of the Commission and self-regulatory organizations to investor concerns;"],[4,"(III) a summary of the most serious problems encountered by investors during the reporting period;"],[4,"(IV) an inventory of the items described in subclause (III) that includes—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78d?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§78d. Securities and Exchange Commission","tname":"Commerce and Trade","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 78d-1","url":"https://www.law.cornell.edu/uscode/text/15/78d-1","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(1946)","(1958)","(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"30, 30","1":"4, 36"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"3, 24"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","by":{"0":"3, 24","2":"9"}},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","by":{"0":"3, 24","2":"9"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)(1)"],"by":{"0":"3","1":"7, 11, 69-72"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","by":{"0":"5"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"by":{"0":"5, 10, 61","2":"21"}},{"t":"usc","label":"5 U.S.C. § 1215","url":"https://www.law.cornell.edu/uscode/text/5/1215","stext":{"head":"§1215. Disciplinary action","paras":[[0,"(a)(1) Except as provided in subsection (b), if the Special Counsel determines that disciplinary action should be taken against any employee for having—"],[1,"(A) committed a prohibited personnel practice,"],[1,"(B) violated the provisions of any law, rule, or regulation, or engaged in any other conduct within the jurisdiction of the Special Counsel as described in section 1216, or"],[1,"(C) knowingly and willfully refused or failed to comply with an order of the Merit Systems Protection Board,"],[0,"the Special Counsel shall prepare a written complaint against the employee containing the Special Counsel's determination, together with a statement of supporting facts, and present the complaint and statement to the employee and the Board, in accordance with this subsection."],[0,"(2) Any employee against whom a complaint has been presented to the Merit Systems Protection Board under paragraph (1) is entitled to—"],[1,"(A) a reasonable time to answer orally and in writing, and to furnish affidavits and other documentary evidence in support of the answer;"],[1,"(B) be represented by an attorney or other representative;"],[1,"(C) a hearing before the Board or an administrative law judge appointed under section 3105 and designated by the Board;"],[1,"(D) have a transcript kept of any hearing under subparagraph (C); and"],[1,"(E) a written decision and reasons therefor at the earliest practicable date, including a copy of any final order imposing disciplinary action."],[0,"(3)(A) A final order of the Board may impose—"],[1,"(i) disciplinary action consisting of removal, reduction in grade, debarment from Federal employment for a period not to exceed 5 years, suspension, or reprimand;"],[1,"(ii) an assessment of a civil penalty not to exceed $1,000; or"],[1,"(iii) any combination of disciplinary actions described under clause (i) and an assessment described under clause (ii)."],[0,"(B) In any case brought under paragraph (1) in which the Board finds that an employee has committed a prohibited personnel practice under section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D), the Board may impose disciplinary action if the Board finds that the activity protected under section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) was a significant motivating factor, even if other factors also motivated the decision, for the employee's decision to take, fail to take, or threaten to take or fail to take a personnel action, unless that employee demonstrates, by a preponderance of the evidence, that the employee would have taken, failed to take, or threatened to take or fail to take the same personnel action, in the absence of such protected activity."],[0,"(4) There may be no administrative appeal from an order of the Board. An employee subject to a final order imposing disciplinary action under this subsection may obtain judicial review of the order by filing a petition therefor with such court, and within such time, as provided for under section 7703(b)."],[0,"(5) In the case of any State or local officer or employee under chapter 15, the Board shall consider the case in accordance with the provisions of such chapter."],[0,"(b) In the case of an employee in a confidential, policy-making, policy-determining, or policy-advocating position appointed by the President, by and with the advice and consent of the Senate (other than an individual in the Foreign Service of the United States), the complaint and statement referred to in subsection (a)(1), together with any response of the employee, shall be presented to the President for appropriate action in lieu of being presented under subsection (a)."],[0,"(c)(1) In the case of members of the uniformed services and individuals employed by any person under contract with an agency to provide goods or services, the Special Counsel may transmit recommendations for disciplinary or other appropriate action (including the evidence on which such recommendations are based) to the head of the agency concerned."],[0,"(2) In any case in which the Special Counsel transmits recommendations to an agency head under paragraph (1), the agency head shall, within 60 days after receiving such recommendations, transmit a report to the Special Counsel on each recommendation and the action taken, or proposed to be taken, with respect to each such recommendation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1215?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1215. Disciplinary action","tname":"Government Organization and Employees","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 3105","url":"https://www.law.cornell.edu/uscode/text/5/3105","by":{"0":"4, 5","2":"21"}},{"t":"usc","label":"5 U.S.C. § 3502","url":"https://www.law.cornell.edu/uscode/text/5/3502","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 7104","url":"https://www.law.cornell.edu/uscode/text/5/7104","subs":["(b)"],"by":{"0":"64"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","subs":["(a)","(b)(A)","(b)(B)","(b)(C)"],"stext":{"head":"§7521. Actions against administrative law judges","paras":[[0,"(a) An action may be taken against an administrative law judge appointed under section 3105 of this title by the agency in which the administrative law judge is employed only for good cause established and determined by the Merit Systems Protection Board on the record after opportunity for hearing before the Board."],[0,"(b) The actions covered by this section are—"],[1,"(1) a removal;"],[1,"(2) a suspension;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but do not include—"],[1,"(A) a suspension or removal under section 7532 of this title;"],[1,"(B) a reduction-in-force action under section 3502 of this title; or"],[1,"(C) any action initiated under section 1215 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7521?type=usc&year=mostrecent&link-type=html"},"head":"§7521. Actions against administrative law judges","tname":"Government Organization and Employees","by":{"0":"6, 6, 6, 6, 6","1":"63","2":"18, 21, 22, 24-26, 29, 17, 21, 27, 28"}},{"t":"usc","label":"5 U.S.C. § 7532","url":"https://www.law.cornell.edu/uscode/text/5/7532","subs":["(b)"],"by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","by":{"0":"6"}},{"t":"usc","label":"7 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/7/9","subs":["(4)","(10)"],"stext":{"head":"§9. Prohibition regarding manipulation and false information","paras":[[0,"(1) Prohibition against manipulation"],[0,"It shall be unlawful for any person, directly or indirectly, to use or employ, or attempt to use or employ, in connection with any swap, or a contract of sale of any commodity in interstate commerce, or for future delivery on or subject to the rules of any registered entity, any manipulative or deceptive device or contrivance, in contravention of such rules and regulations as the Commission shall promulgate by not later than 1 year after July 21, 2010, provided no rule or regulation promulgated by the Commission shall require any person to disclose to another person nonpublic information that may be material to the market price, rate, or level of the commodity transaction, except as necessary to make any statement made to the other person in or in connection with the transaction not misleading in any material respect."],[0,"(A) Special provision for manipulation by false reporting"],[1,"Unlawful manipulation for purposes of this paragraph shall include, but not be limited to, delivering, or causing to be delivered for transmission through the mails or interstate commerce, by any means of communication whatsoever, a false or misleading or inaccurate report concerning crop or market information or conditions that affect or tend to affect the price of any commodity in interstate commerce, knowing, or acting in reckless disregard of the fact that such report is false, misleading or inaccurate."],[0,"(B) Effect on other law"],[1,"Nothing in this paragraph shall affect, or be construed to affect, the applicability of section 13(a)(2) of this title."],[0,"(C) Good faith mistakes"],[1,"Mistakenly transmitting, in good faith, false or misleading or inaccurate information to a price reporting service would not be sufficient to violate paragraph (1)(A)."],[0,"(2) Prohibition regarding false information"],[0,"It shall be unlawful for any person to make any false or misleading statement of a material fact to the Commission, including in any registration application or any report filed with the Commission under this chapter, or any other information relating to a swap, or a contract of sale of a commodity, in interstate commerce, or for future delivery on or subject to the rules of any registered entity, or to omit to state in any such statement any material fact that is necessary to make any statement of a material fact made not misleading in any material respect, if the person knew, or reasonably should have known, the statement to be false or misleading."],[0,"(3) Other manipulation"],[0,"In addition to the prohibition in paragraph (1), it shall be unlawful for any person, directly or indirectly, to manipulate or attempt to manipulate the price of any swap, or of any commodity in interstate commerce, or for future delivery on or subject to the rules of any registered entity."],[0,"(4) Enforcement"],[0,"(A) Authority of Commission"],[1,"If the Commission has reason to believe that any person (other than a registered entity) is violating or has violated this section, or any other provision of this chapter (including any rule, regulation, or order of the Commission promulgated in accordance with this section or any other provision of this chapter), the Commission may serve upon the person a complaint."],[0,"(B) Contents of complaint"],[1,"A complaint under subparagraph (A) shall—"],[2,"(i) contain a description of the charges against the person that is the subject of the complaint; and"],[2,"(ii) have attached or contain a notice of hearing that specifies the date and location of the hearing regarding the complaint."],[0,"(C) Hearing"],[1,"A hearing described in subparagraph (B)(ii)—"],[2,"(i) shall be held not later than 3 days after service of the complaint described in subparagraph (A);"],[2,"(ii) shall require the person to show cause regarding why—"],[3,"(I) an order should not be made—"],[4,"(aa) to prohibit the person from trading on, or subject to the rules of, any registered entity; and"],[4,"(bb) to direct all registered entities to refuse all privileges to the person until further notice of the Commission; and"],[3,"(II) the registration of the person, if registered with the Commission in any capacity, should not be suspended or revoked; and"],[2,"(iii) may be held before—"],[3,"(I) the Commission; or"],[3,"(II) an administrative law judge designated by the Commission, under which the administrative law judge shall ensure that all evidence is recorded in written form and submitted to the Commission."],[0,"(5) Subpoena"],[0,"For the purpose of securing effective enforcement of the provisions of this chapter, for the purpose of any investigation or proceeding under this chapter, and for the purpose of any action taken under section 16(f) of this title, any member of the Commission or any Administrative Law Judge or other officer designated by the Commission (except as provided in paragraph (7)) may administer oaths and affirmations, subpoena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records that the Commission deems relevant or material to the inquiry."],[0,"(6) Witnesses"],[0,"The attendance of witnesses and the production of any such records may be required from any place in the United States, any State, or any foreign country or jurisdiction at any designated place of hearing."],[0,"(7) Service"],[0,"A subpoena issued under this section 1 may be served upon any person who is not to be found within the territorial jurisdiction of any court of the United States in such manner as the Federal Rules of Civil Procedure prescribe for service of process in a foreign country, except that a subpoena to be served on a person who is not to be found within the territorial jurisdiction of any court of the United States may be issued only on the prior approval of the Commission."],[0,"(8) Refusal to obey"],[0,"In case of contumacy by, or refusal to obey a subpoena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction in which the investigation or proceeding is conducted, or where such person resides or transacts business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. Such court may issue an order requiring such person to appear before the Commission or member or Administrative Law Judge or other officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question."],[0,"(9) Failure to obey"],[0,"Any failure to obey such order of the court may be punished by the court as a contempt thereof. All process in any such case may be served in the judicial district wherein such person is an inhabitant or transacts business or wherever such person may be found."],[0,"(10) Evidence"],[0,"On the receipt of evidence under paragraph (4)(C)(iii), the Commission may—"],[1,"(A) prohibit the person that is the subject of the hearing from trading on, or subject to the rules of, any registered entity and require all registered entities to refuse the person all privileges on the registered entities for such period as the Commission may require in the order;"],[1,"(B) if the person is registered with the Commission in any capacity, suspend, for a period not to exceed 180 days, or revoke, the registration of the person;"],[1,"(C) assess such person—"],[2,"(i) a civil penalty of not more than an amount equal to the greater of—"],[3,"(I) $140,000; or"],[3,"(II) triple the monetary gain to such person for each such violation; or"],[2,"(ii) in any case of manipulation or attempted manipulation in violation of this section or section 13(a)(2) of this title, a civil penalty of not more than an amount equal to the greater of—"],[3,"(I) $1,000,000; or"],[3,"(II) triple the monetary gain to the person for each such violation; and"],[1,"(D) require restitution to customers of damages proximately caused by violations of the person."],[0,"(11) Orders"],[0,"(A) Notice"],[1,"The Commission shall provide to a person described in paragraph (10) and the appropriate governing board of the registered entity notice of the order described in paragraph (10) by—"],[2,"(i) registered mail;"],[2,"(ii) certified mail; or"],[2,"(iii) personal delivery."],[0,"(B) Review"],[0,"(i) In general"],[2,"A person described in paragraph (10) may obtain a review of the order or such other equitable relief as determined to be appropriate by a court described in clause (ii)."],[0,"(ii) Petition"],[2,"To obtain a review or other relief under clause (i), a person may, not later than 15 days after notice is given to the person under clause (i), file a written petition to set aside the order with the United States Court of Appeals—"],[3,"(I) for the circuit in which the petitioner carries out the business of the petitioner; or"],[3,"(II) in the case of an order denying registration, the circuit in which the principal place of business of the petitioner is located, as listed on the application for registration of the petitioner."],[0,"(C) Procedure"],[0,"(i) Duty of clerk of appropriate court"],[2,"The clerk of the appropriate court under subparagraph (B)(ii) shall transmit to the Commission a copy of a petition filed under subparagraph (B)(ii)."],[0,"(ii) Duty of Commission"],[2,"In accordance with section 2112 of title 28, the Commission shall file in the appropriate court described in subparagraph (B)(ii) the record theretofore made."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/9?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9. Prohibition regarding manipulation and false information","tname":"Agriculture","by":{"0":"33, 33"}},{"t":"usc","label":"7 U.S.C. § 13a-1","url":"https://www.law.cornell.edu/uscode/text/7/13a-1","subs":["(a)","(d)"],"by":{"0":"33, 33"}},{"t":"usc","label":"7 U.S.C. § 6992","url":"https://www.law.cornell.edu/uscode/text/7/6992","subs":["(b)(2)"],"by":{"0":"55"}},{"t":"usc","label":"10 U.S.C. § 942","url":"https://www.law.cornell.edu/uscode/text/10/942","subs":["(c)"],"by":{"0":"55, 64"}},{"t":"usc","label":"12 U.S.C. § 5563","url":"https://www.law.cornell.edu/uscode/text/12/5563","subs":["(a)"],"stext":{"head":"§5563. Hearings and adjudication proceedings","paras":[[0,"(a) In general"],[0,"The Bureau is authorized to conduct hearings and adjudication proceedings with respect to any person in the manner prescribed by chapter 5 of title 5 in order to ensure or enforce compliance with—"],[1,"(1) the provisions of this title,1 including any rules prescribed by the Bureau under this title; 1 and"],[1,"(2) any other Federal law that the Bureau is authorized to enforce, including an enumerated consumer law, and any regulations or order prescribed thereunder, unless such Federal law specifically limits the Bureau from conducting a hearing or adjudication proceeding and only to the extent of such limitation."],[0,"(b) Special rules for cease-and-desist proceedings"],[0,"(1) Orders authorized"],[0,"(A) In general"],[2,"If, in the opinion of the Bureau, any covered person or service provider is engaging or has engaged in an activity that violates a law, rule, or any condition imposed in writing on the person by the Bureau, the Bureau may, subject to sections 5514, 5515, and 5516 of this title, issue and serve upon the covered person or service provider a notice of charges in respect thereof."],[0,"(B) Content of notice"],[2,"The notice under subparagraph (A) shall contain a statement of the facts constituting the alleged violation or violations, and shall fix a time and place at which a hearing will be held to determine whether an order to cease and desist should issue against the covered person or service provider, such hearing to be held not earlier than 30 days nor later than 60 days after the date of service of such notice, unless an earlier or a later date is set by the Bureau, at the request of any party so served."],[0,"(C) Consent"],[2,"Unless the party or parties served under subparagraph (B) appear at the hearing personally or by a duly authorized representative, such person shall be deemed to have consented to the issuance of the cease-and-desist order."],[0,"(D) Procedure"],[2,"In the event of consent under subparagraph (C), or if, upon the record, made at any such hearing, the Bureau finds that any violation specified in the notice of charges has been established, the Bureau may issue and serve upon the covered person or service provider an order to cease and desist from the violation or practice. Such order may, by provisions which may be mandatory or otherwise, require the covered person or service provider to cease and desist from the subject activity, and to take affirmative action to correct the conditions resulting from any such violation."],[0,"(2) Effectiveness of order"],[1,"A cease-and-desist order shall become effective at the expiration of 30 days after the date of service of an order under paragraph (1) upon the covered person or service provider concerned (except in the case of a cease-and-desist order issued upon consent, which shall become effective at the time specified therein), and shall remain effective and enforceable as provided therein, except to such extent as the order is stayed, modified, terminated, or set aside by action of the Bureau or a reviewing court."],[0,"(3) Decision and appeal"],[1,"Any hearing provided for in this subsection shall be held in the Federal judicial district or in the territory in which the residence or principal office or place of business of the person is located unless the person consents to another place, and shall be conducted in accordance with the provisions of chapter 5 of title 5. After such hearing, and within 90 days after the Bureau has notified the parties that the case has been submitted to the Bureau for final decision, the Bureau shall render its decision (which shall include findings of fact upon which its decision is predicated) and shall issue and serve upon each party to the proceeding an order or orders consistent with the provisions of this section. Judicial review of any such order shall be exclusively as provided in this subsection. Unless a petition for review is timely filed in a court of appeals of the United States, as provided in paragraph (4), and thereafter until the record in the proceeding has been filed as provided in paragraph (4), the Bureau may at any time, upon such notice and in such manner as the Bureau shall determine proper, modify, terminate, or set aside any such order. Upon filing of the record as provided, the Bureau may modify, terminate, or set aside any such order with permission of the court."],[0,"(4) Appeal to court of appeals"],[1,"Any party to any proceeding under this subsection may obtain a review of any order served pursuant to this subsection (other than an order issued with the consent of the person concerned) by the filing in the court of appeals of the United States for the circuit in which the principal office of the covered person is located, or in the United States Court of Appeals for the District of Columbia Circuit, within 30 days after the date of service of such order, a written petition praying that the order of the Bureau be modified, terminated, or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Bureau, and thereupon the Bureau shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon the filing of such petition, such court shall have jurisdiction, which upon the filing of the record shall except as provided in the last sentence of paragraph (3) be exclusive, to affirm, modify, terminate, or set aside, in whole or in part, the order of the Bureau. Review of such proceedings shall be had as provided in chapter 7 of title 5. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court of the United States, upon certiorari, as provided in section 1254 of title 28."],[0,"(5) No stay"],[1,"The commencement of proceedings for judicial review under paragraph (4) shall not, unless specifically ordered by the court, operate as a stay of any order issued by the Bureau."],[0,"(c) Special rules for temporary cease-and-desist proceedings"],[0,"(1) In general"],[1,"Whenever the Bureau determines that the violation specified in the notice of charges served upon a person, including a service provider, pursuant to subsection (b), or the continuation thereof, is likely to cause the person to be insolvent or otherwise prejudice the interests of consumers before the completion of the proceedings conducted pursuant to subsection (b), the Bureau may issue a temporary order requiring the person to cease and desist from any such violation or practice and to take affirmative action to prevent or remedy such insolvency or other condition pending completion of such proceedings. Such order may include any requirement authorized under this part. Such order shall become effective upon service upon the person and, unless set aside, limited, or suspended by a court in proceedings authorized by paragraph (2), shall remain effective and enforceable pending the completion of the administrative proceedings pursuant to such notice and until such time as the Bureau shall dismiss the charges specified in such notice, or if a cease-and-desist order is issued against the person, until the effective date of such order."],[0,"(2) Appeal"],[1,"Not later than 10 days after the covered person or service provider concerned has been served with a temporary cease-and-desist order, the person may apply to the United States district court for the judicial district in which the residence or principal office or place of business of the person is located, or the United States District Court for the District of Columbia, for an injunction setting aside, limiting, or suspending the enforcement, operation, or effectiveness of such order pending the completion of the administrative proceedings pursuant to the notice of charges served upon the person under subsection (b), and such court shall have jurisdiction to issue such injunction."],[0,"(3) Incomplete or inaccurate records"],[0,"(A) Temporary order"],[2,"If a notice of charges served under subsection (b) specifies, on the basis of particular facts and circumstances, that the books and records of a covered person or service provider are so incomplete or inaccurate that the Bureau is unable to determine the financial condition of that person or the details or purpose of any transaction or transactions that may have a material effect on the financial condition of that person, the Bureau may issue a temporary order requiring—"],[3,"(i) the cessation of any activity or practice which gave rise, whether in whole or in part, to the incomplete or inaccurate state of the books or records; or"],[3,"(ii) affirmative action to restore such books or records to a complete and accurate state, until the completion of the proceedings under subsection (b)(1)."],[0,"(B) Effective period"],[2,"Any temporary order issued under subparagraph (A)—"],[3,"(i) shall become effective upon service; and"],[3,"(ii) unless set aside, limited, or suspended by a court in proceedings under paragraph (2), shall remain in effect and enforceable until the earlier of—"],[4,"(I) the completion of the proceeding initiated under subsection (b) in connection with the notice of charges; or"],[4,"(II) the date the Bureau determines, by examination or otherwise, that the books and records of the covered person or service provider are accurate and reflect the financial condition thereof."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5563?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§5563. Hearings and adjudication proceedings","tname":"Banks and Banking","by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 5564","url":"https://www.law.cornell.edu/uscode/text/12/5564","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 5565","url":"https://www.law.cornell.edu/uscode/text/12/5565","subs":["(a)(1)","(a)(2)(H)"],"by":{"0":"33, 33"}},{"t":"usc","label":"16 U.S.C. § 1852","url":"https://www.law.cornell.edu/uscode/text/16/1852","subs":["(b)(6)(B)"],"by":{"0":"64"}},{"t":"usc","label":"21 U.S.C. § 335b","url":"https://www.law.cornell.edu/uscode/text/21/335b","subs":["(b)(1)"],"stext":{"head":"§335b. Civil penalties","paras":[[0,"(a) In general"],[0,"Any person that the Secretary finds—"],[1,"(1) knowingly made or caused to be made, to any officer, employee, or agent of the Department of Health and Human Services, a false statement or misrepresentation of a material fact in connection with an abbreviated drug application,"],[1,"(2) bribed or attempted to bribe or paid or attempted to pay an illegal gratuity to any officer, employee, or agent of the Department of Health and Human Services in connection with an abbreviated drug application,"],[1,"(3) destroyed, altered, removed, or secreted, or procured the destruction, alteration, removal, or secretion of, any material document or other material evidence which was the property of or in the possession of the Department of Health and Human Services for the purpose of interfering with that Department's discharge of its responsibilities in connection with an abbreviated drug application,"],[1,"(4) knowingly failed to disclose, to an officer or employee of the Department of Health and Human Services, a material fact which such person had an obligation to disclose relating to any drug subject to an abbreviated drug application,"],[1,"(5) knowingly obstructed an investigation of the Department of Health and Human Services into any drug subject to an abbreviated drug application,"],[1,"(6) is a person that has an approved or pending drug product application and has knowingly—"],[2,"(A) employed or retained as a consultant or contractor, or"],[2,"(B) otherwise used in any capacity the services of,"],[1,"a person who was debarred under section 335a of this title, or"],[1,"(7) is an individual debarred under section 335a of this title and, during the period of debarment, provided services in any capacity to a person that had an approved or pending drug product application,"],[0,"shall be liable to the United States for a civil penalty for each such violation in an amount not to exceed $250,000 in the case of an individual and $1,000,000 in the case of any other person."],[0,"(b) Procedure"],[0,"(1) In general"],[0,"(A) Action by the Secretary"],[2,"A civil penalty under subsection (a) shall be assessed by the Secretary on a person by an order made on the record after an opportunity for an agency hearing on disputed issues of material fact and the amount of the penalty. In the course of any investigation or hearing under this subparagraph, the Secretary may administer oaths and affirmations, examine witnesses, receive evidence, and issue subpoenas requiring the attendance and testimony of witnesses and the production of evidence that relates to the matter under investigation."],[0,"(B) Action by the Attorney General"],[2,"In lieu of a proceeding under subparagraph (A), the Attorney General may, upon request of the Secretary, institute a civil action to recover a civil money penalty in the amount and for any of the acts set forth in subsection (a). Such an action may be instituted separately from or in connection with any other claim, civil or criminal, initiated by the Attorney General under this chapter."],[0,"(2) Amount"],[1,"In determining the amount of a civil penalty under paragraph (1), the Secretary or the court shall take into account the nature, circumstances, extent, and gravity of the act subject to penalty, the person's ability to pay, the effect on the person's ability to continue to do business, any history of prior, similar acts, and such other matters as justice may require."],[0,"(3) Limitation on actions"],[1,"No action may be initiated under this section—"],[2,"(A) with respect to any act described in subsection (a) that occurred before May 13, 1992, or"],[2,"(B) more than 6 years after the date when facts material to the act are known or reasonably should have been known by the Secretary but in no event more than 10 years after the date the act took place."],[0,"(c) Judicial review"],[0,"Any person that is the subject of an adverse decision under subsection (b)(1)(A) may obtain a review of such decision by the United States Court of Appeals for the District of Columbia or for the circuit in which the person resides, by filing in such court (within 60 days following the date the person is notified of the Secretary's decision) a petition requesting that the decision be modified or set aside."],[0,"(d) Recovery of penalties"],[0,"The Attorney General may recover any civil penalty (plus interest at the currently prevailing rates from the date the penalty became final) assessed under subsection (b)(1)(A) in an action brought in the name of the United States. The amount of such penalty may be deducted, when the penalty has become final, from any sums then or later owing by the United States to the person against whom the penalty has been assessed. In an action brought under this subsection, the validity, amount, and appropriateness of the penalty shall not be subject to judicial review."],[0,"(e) Informants"],[0,"The Secretary may award to any individual (other than an officer or employee of the Federal Government or a person who materially participated in any conduct described in subsection (a)) who provides information leading to the imposition of a civil penalty under this section an amount not to exceed—"],[1,"(1) $250,000, or"],[1,"(2) one-half of the penalty so imposed and collected,"],[0,"whichever is less. The decision of the Secretary on such award shall not be reviewable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/335b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§335b. Civil penalties","tname":"Food and Drugs","by":{"0":"33"}},{"t":"usc","label":"22 U.S.C. § 4106","url":"https://www.law.cornell.edu/uscode/text/22/4106","subs":["(e)"],"by":{"0":"64"}},{"t":"usc","label":"22 U.S.C. § 4135","url":"https://www.law.cornell.edu/uscode/text/22/4135","subs":["(d)"],"by":{"0":"64"}},{"t":"usc","label":"26 U.S.C. § 7443","url":"https://www.law.cornell.edu/uscode/text/26/7443","by":{"0":"64"}},{"t":"usc","label":"28 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/28/152","subs":["(e)"],"by":{"0":"54, 64"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(b)(2)(H)"],"by":{"0":"26"}},{"t":"usc","label":"28 U.S.C. § 176","url":"https://www.law.cornell.edu/uscode/text/28/176","subs":["(b)"],"by":{"0":"64"}},{"t":"usc","label":"28 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/28/631","subs":["(i)"],"by":{"0":"54, 64"}},{"t":"usc","label":"29 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/29/153","subs":["(a)"],"by":{"0":"64"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(a)","(b)","(g)"],"stext":{"head":"§1319. Enforcement","paras":[[0,"(a) State enforcement; compliance orders"],[0,"(1) Whenever, on the basis of any information available to him, the Administrator finds that any person is in violation of any condition or limitation which implements section 1311, 1312, 1316, 1317, 1318, 1328, or 1345 of this title in a permit issued by a State under an approved permit program under section 1342 or 1344 of this title he shall proceed under his authority in paragraph (3) of this subsection or he shall notify the person in alleged violation and such State of such finding. If beyond the thirtieth day after the Administrator's notification the State has not commenced appropriate enforcement action, the Administrator shall issue an order requiring such person to comply with such condition or limitation or shall bring a civil action in accordance with subsection (b) of this section."],[0,"(2) Whenever, on the basis of information available to him, the Administrator finds that violations of permit conditions or limitations as set forth in paragraph (1) of this subsection are so widespread that such violations appear to result from a failure of the State to enforce such permit conditions or limitations effectively, he shall so notify the State. If the Administrator finds such failure extends beyond the thirtieth day after such notice, he shall give public notice of such finding. During the period beginning with such public notice and ending when such State satisfies the Administrator that it will enforce such conditions and limitations (hereafter referred to in this section as the period of \"federally assumed enforcement\"), except where an extension has been granted under paragraph (5)(B) of this subsection, the Administrator shall enforce any permit condition or limitation with respect to any person—"],[1,"(A) by issuing an order to comply with such condition or limitation, or"],[1,"(B) by bringing a civil action under subsection (b) of this section."],[0,"(3) Whenever on the basis of any information available to him the Administrator finds that any person is in violation of section 1311, 1312, 1316, 1317, 1318, 1322(p), 1328, or 1345 of this title, or is in violation of any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by him or by a State or in a permit issued under section 1344 of this title by a State, he shall issue an order requiring such person to comply with such section or requirement, or he shall bring a civil action in accordance with subsection (b) of this section."],[0,"(4) A copy of any order issued under this subsection shall be sent immediately by the Administrator to the State in which the violation occurs and other affected States. In any case in which an order under this subsection (or notice to a violator under paragraph (1) of this subsection) is issued to a corporation, a copy of such order (or notice) shall be served on any appropriate corporate officers. An order issued under this subsection relating to a violation of section 1318 of this title shall not take effect until the person to whom it is issued has had an opportunity to confer with the Administrator concerning the alleged violation."],[0,"(5)(A) Any order issued under this subsection shall be by personal service, shall state with reasonable specificity the nature of the violation, and shall specify a time for compliance not to exceed thirty days in the case of a violation of an interim compliance schedule or operation and maintenance requirement and not to exceed a time the Administrator determines to be reasonable in the case of a violation of a final deadline, taking into account the seriousness of the violation and any good faith efforts to comply with applicable requirements."],[0,"(B) The Administrator may, if he determines (i) that any person who is a violator of, or any person who is otherwise not in compliance with, the time requirements under this chapter or in any permit issued under this chapter, has acted in good faith, and has made a commitment (in the form of contracts or other securities) of necessary resources to achieve compliance by the earliest possible date after July 1, 1977, but not later than April 1, 1979; (ii) that any extension under this provision will not result in the imposition of any additional controls on any other point or nonpoint source; (iii) that an application for a permit under section 1342 of this title was filed for such person prior to December 31, 1974; and (iv) that the facilities necessary for compliance with such requirements are under construction, grant an extension of the date referred to in section 1311(b)(1)(A) of this title to a date which will achieve compliance at the earliest time possible but not later than April 1, 1979."],[0,"(6) Whenever, on the basis of information available to him, the Administrator finds (A) that any person is in violation of section 1311(b)(1)(A) or (C) of this title, (B) that such person cannot meet the requirements for a time extension under section 1311(i)(2) of this title, and (C) that the most expeditious and appropriate means of compliance with this chapter by such person is to discharge into a publicly owned treatment works, then, upon request of such person, the Administrator may issue an order requiring such person to comply with this chapter at the earliest date practicable, but not later than July 1, 1983, by discharging into a publicly owned treatment works if such works concur with such order. Such order shall include a schedule of compliance."],[0,"(b) Civil actions"],[0,"The Administrator is authorized to commence a civil action for appropriate relief, including a permanent or temporary injunction, for any violation for which he is authorized to issue a compliance order under subsection (a) of this section. Any action under this subsection may be brought in the district court of the United States for the district in which the defendant is located or resides or is doing business, and such court shall have jurisdiction to restrain such violation and to require compliance. Notice of the commencement of such action shall be given immediately to the appropriate State."],[0,"(c) Criminal penalties"],[0,"(1) Negligent violations"],[1,"Any person who—"],[2,"(A) negligently violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) negligently introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in any permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $2,500 nor more than $25,000 per day of violation, or by imprisonment for not more than 1 year, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $50,000 per day of violation, or by imprisonment of not more than 2 years, or by both."],[0,"(2) Knowing violations"],[1,"Any person who—"],[2,"(A) knowingly violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) knowingly introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in a permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $5,000 nor more than $50,000 per day of violation, or by imprisonment for not more than 3 years, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $100,000 per day of violation, or by imprisonment of not more than 6 years, or by both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1319?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1319. Enforcement","tname":"Navigation and Navigable Waters","by":{"0":"33, 33, 33"}},{"t":"usc","label":"35 U.S.C. § 282","url":"https://www.law.cornell.edu/uscode/text/35/282","subs":["(b)(2)","(b)(3)"],"by":{"0":"33, 33"}},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","subs":["(b)(2)"],"by":{"0":"55, 64"}},{"t":"usc","label":"38 U.S.C. § 7253","url":"https://www.law.cornell.edu/uscode/text/38/7253","by":{"0":"55, 64"}},{"t":"usc","label":"39 U.S.C. § 3018","url":"https://www.law.cornell.edu/uscode/text/39/3018","subs":["(c)","(d)","(g)"],"stext":{"head":"§3018. Hazardous material","paras":[[0,"(a) In General.—The Postal Service shall prescribe regulations for the safe transportation of hazardous material in the mail."],[0,"(b) Prohibitions.—No person may—"],[1,"(1) mail or cause to be mailed hazardous material that has been declared by statute or Postal Service regulation to be nonmailable;"],[1,"(2) mail or cause to be mailed hazardous material in violation of any statute or Postal Service regulation restricting the time, place, or manner in which hazardous material may be mailed; or"],[1,"(3) manufacture, distribute, or sell any container, packaging kit, or similar device that—"],[2,"(A) is represented, marked, certified, or sold by such person for use in the mailing of hazardous material; and"],[2,"(B) fails to conform with any statute or Postal Service regulation setting forth standards for a container, packaging kit, or similar device used for the mailing of hazardous material."],[0,"(c) Civil Penalty; Clean-Up Costs and Damages.—"],[1,"(1) In general.—A person who knowingly violates this section or a regulation prescribed under this section shall be liable for—"],[2,"(A) a civil penalty of at least $250, but not more than $100,000, for each violation;"],[2,"(B) the costs of any clean-up associated with each violation; and"],[2,"(C) damages."],[1,"(2) Knowing action.—A person acts knowingly for purposes of paragraph (1) when—"],[2,"(A) the person has actual knowledge of the facts giving rise to the violation; or"],[2,"(B) a reasonable person acting in the circumstances and exercising reasonable care would have had that knowledge."],[1,"(3) Separate violations.—"],[2,"(A) Violations over time.—A separate violation under this subsection occurs for each day hazardous material, mailed or caused to be mailed in noncompliance with this section, is in the mail."],[2,"(B) Separate items.—A separate violation under this subsection occurs for each item containing hazardous material that is mailed or caused to be mailed in noncompliance with this section."],[0,"(d) Hearings.—The Postal Service may determine that a person has violated this section or a regulation prescribed under this section only after notice and an opportunity for a hearing. Proceedings under this section shall be conducted in accordance with section 3001(m)."],[0,"(e) Penalty Considerations.—In determining the amount of a civil penalty for a violation of this section, the Postal Service shall consider—"],[1,"(1) the nature, circumstances, extent, and gravity of the violation;"],[1,"(2) with respect to the person who committed the violation, the degree of culpability, any history of prior violations, the ability to pay, and any effect on the ability to continue in business;"],[1,"(3) the impact on Postal Service operations; and"],[1,"(4) any other matters that justice requires."],[0,"(f) Civil Actions to Collect.—"],[1,"(1) In general.—In accordance with section 409(d), a civil action may be commenced in an appropriate district court of the United States to collect a civil penalty, clean-up costs, and damages assessed under subsection (c)."],[1,"(2) Compromise.—The Postal Service may compromise the amount of a civil penalty, clean-up costs, and damages assessed under subsection (c) before commencing a civil action with respect to such civil penalty, clean-up costs, and damages under paragraph (1)."],[0,"(g) Civil Judicial Penalties.—"],[1,"(1) In general.—At the request of the Postal Service, the Attorney General may bring a civil action in an appropriate district court of the United States to enforce this section or a regulation prescribed under this section."],[1,"(2) Relief.—The court in a civil action under paragraph (1) may award appropriate relief, including a temporary or permanent injunction, civil penalties as determined in accordance with this section, or punitive damages."],[1,"(3) Construction.—A civil action under this subsection shall be in lieu of civil penalties for the same violation under subsection (c)(1)(A)."],[0,"(h) Deposit of Amounts Collected.—"],[1,"(1) Postal service fund.—Except as provided under paragraph (2), amounts collected under subsection (c)(1)(B) and (C) shall be deposited into the Postal Service Fund under section 2003."],[1,"(2) Treasury.—Amounts collected under subsection (c)(1)(A) and any punitive damages collected under subsection (c)(1)(C) shall be deposited into the Treasury of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/39/3018?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3018. Hazardous material","tname":"Postal Service","by":{"0":"33, 33, 33"}},{"t":"usc","label":"41 U.S.C. § 7105","url":"https://www.law.cornell.edu/uscode/text/41/7105","subs":["(b)(3)"],"by":{"0":"55"}},{"t":"usc","label":"48 U.S.C. § 1424b","url":"https://www.law.cornell.edu/uscode/text/48/1424b","subs":["(a)"],"by":{"0":"54"}},{"t":"usc","label":"48 U.S.C. § 1614","url":"https://www.law.cornell.edu/uscode/text/48/1614","subs":["(a)"],"by":{"0":"54"}},{"t":"usc","label":"48 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/48/1821","subs":["(b)(1)"],"by":{"0":"54"}},{"t":"rule","label":"Fed. R. Crim. P. 7","url":"https://www.law.cornell.edu/rules/frcrmp/rule_7","subs":["(a)"],"by":{"0":"44"}},{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"sum":"The Court held that plain language and the legislative history of the statutes required the SEC to establish defendant’s intent to “deceive, manipulate, or defraud” for violations of Section 10(b) and the part of Section 17(a) that specifically refers to the use of a device, scheme, or artifice with intent to defraud.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Advoc. Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/468/","sc":1,"by":{"1":"72"}},{"t":"case","label":"Alaska Airlines v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"67"}},{"t":"case","label":"Arizona v. Fulminante","cite":"499 U.S. 279","y":1991,"id":"1990/89-839","sc":1,"op":1,"sum":"The Court held that Fulminante was coerced to confess in violation of the Fifth and Fourteenth Amendments. The Court found that \"it was fear of physical violence, absent protection from his friend Sarivola, which motivated Fulminante to confess.\" This motivation invalidated his confession. Since Fulminante's confession to Donna Sarivola was closely tied to his first coerced confession, the Court dismissed both.","sumSrc":"Oyez","by":{"1":"66"}},{"t":"case","label":"Axon Enterprise, Inc., v. F.T.C.","cite":"143 S. Ct. 890","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/890/","sc":1,"op":1,"ar":1,"by":{"1":"4"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"72"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":2,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"1":"42, 54-55, 68-69"}},{"t":"case","label":"Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"op":5,"sum":"Explaining that Congress can “entrust [the] enforcement of statutory rights to an administrative process . . . free from the strictures of the Seventh Amendment,” but must abide by the Amendment when it does so “in an ordinary civil action in the district courts”.","sumSrc":"opinion","by":{"1":"26"}},{"t":"case","label":"Dimick v. Schiedt","cite":"293 U.S. 474","y":1935,"id":"scdb/1934-155","sc":1,"op":1,"sum":"1. Under the Seventh Amendment, a federal court, finding a verdict inadequate, is without power to add to it by refusing to grant the plaintiff a new trial if the defendant will accept an increase which the court deems sufficient. So held in an action for personal injuries due to negligence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12-13"}},{"t":"case","label":"Dura Pharm., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"op":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"1":"65"}},{"t":"case","label":"Garland v. Ming Dai","cite":"141 S. Ct. 1669","y":2021,"id":"2020/19-1155","sc":1,"op":1,"sum":"The Ninth Circuit’s rule in immigration disputes—that in the absence of an explicit adverse credibility determination by an immigration judge or the Board of Immigration Appeals, a reviewing court must treat a petitioning noncitizen’s testimony as credible and true—cannot be reconciled with the terms of the Immigration and Nationality Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"70"}},{"t":"case","label":"Independent Brokers-Dealers Trade Ass’n v. SEC","cite":"442 F.2d 132","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/442/132/","by":{"1":"71"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"sum":"The Court held that Congress, within \"defined limits,\" could vest discretion in Executive officers to make public regulations and direct the details of statutory execution. The Court argued that the same principle that allowed Congress to fix rates in interstate commerce also enabled it to remit to a rate-making body under the control of the Executive branch.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Kixmiller v. SEC","cite":"492 F.2d 641","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/492/641/","by":{"1":"71"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"1":"12-13"}},{"t":"case","label":"Murphy v. Nat'l Collegiate Athletic Ass'n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"1":"68"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"1":"54"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"op":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"59"}},{"t":"case","label":"Northern Pipeline Constr. Co. v. Marathon Pipeline Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"op":9,"ar":3,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"1":"28, 31"}},{"t":"case","label":"Railroad Retirement Bd. v. Alton R. Co.","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"op":1,"sum":"1. The power of Congress to regulate interstate commerce is subject to the guaranty of due process in the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"68"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"72"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"sum":"The Court held that the judges' actions were not valid de facto. The Court reasoned that a defendant who made a timely challenge to the constitutional validity of the appointment of an officer who adjudicates his case was entitled to a decision on the merits of the question and whatever relief may be appropriate if a violation had occurred.","sumSrc":"Oyez","by":{"1":"65-67"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"70"}},{"t":"case","label":"(xi) Social Sec. Admin. v. Brennan","cite":"27 M.S.P.R. 242","y":1985,"url":"https://www.courtlistener.com/c/M.S.P.R./27/242/","by":{"1":"63"}},{"t":"case","label":"Social Sec. Admin. v. Glover","cite":"23 M.S.P.R. 57","y":1984,"url":"https://www.courtlistener.com/c/M.S.P.R./23/57/","by":{"1":"63"}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"sum":"After an on-the-record hearing before an Administrative Law Judge and review by the Securities and Exchange Commission (SEC) in which the preponderance-of-the-evidence standard of proof was employed, the SEC held that petitioner had violated various antifraud provisions of the federal securities laws, and sanctions were imposed. Petitioner sought review in the Court of Appeals on the alleged ground, inter alia, that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"71"}},{"t":"case","label":"Thomas v. Union Carbide Agric. Prods. Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"op":5,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) requires manufacturers of pesticides, as a precondition for registering a pesticide, to submit research data to the Environmental Protection Agency (EPA) concerning the product's health, safety, and environmental effects, and authorizes EPA to use previously submitted data in considering an application for registration of a similar product by another …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 38-39","2":"7, 8"}},{"t":"case","label":"United States v. Bitty","cite":"208 U.S. 393","y":1908,"id":"scdb/1907-081","sc":1,"sum":"It is within the power of Congress to determine the regulations and exceptions under which this court shall exercise appellate jurisdiction in cases other than those in which this court has original jurisdiction and to which the judicial power of the United States extends; and the act of March 2, 1907, c. 2564, 34 Stat. 1246, permitting the United States to prosecute a writ of error directly from this court to the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"United States v. Wonson","cite":"28 F. Cas. 745","y":1812,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./28/745/","by":{"1":"12"}},{"t":"case","label":"(xii) Weaver v. Massachusetts","cite":"582 U.S. 286","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/286/","sc":1,"by":{"1":"66"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 437","y":2001,"url":"https://supreme.justia.com/cases/federal/us/531/437/","sc":1,"by":{"1":"49"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"85 S. Ct. 551","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45-56"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"1":"72"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"1":"47"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"1":"10,52, 54"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"1":"7-9, 12-13, 23, 25-46","2":"1, 3-6, 11-16, 29"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","by":{"1":"71"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"69-71","2":"30"}},{"t":"reg","label":"5 C.F.R. § 1201.140","url":"https://www.ecfr.gov/current/title-5/section-1201.140","subs":["(b)"],"by":{"1":"63"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","by":{"1":"7, 69"}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","by":{"1":"7, 69"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","subs":["(b)"],"by":{"1":"4"}},{"t":"reg","label":"17 C.F.R. § 275.206","url":"https://www.ecfr.gov/current/title-17/section-275.206","subs":["(4)"],"by":{"1":"4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","by":{"1":"69-70"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"3, 8"}},{"t":"law","label":"Pub. L. No. 101-429","url":"https://www.govinfo.gov/link/statute/104/931","by":{"1":"3"}},{"t":"case","label":"Allen v. Cooper","cite":"140 S. Ct. 994","y":2020,"id":"2019/18-877","sc":1,"sum":"The Court held that the Copyright Remedy Clarification Act was not a valid abrogation of state sovereign immunity to allow authors of original expression to sue states who infringe their federal copyrights.","sumSrc":"Oyez","by":{"2":"5, 12"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Free Enter. Fund v. PCAOB: 537 F.3d 667, (D.C. Cir. 2008), aff ’d in part rev’d in part and remanded","cite":"561 U.S. 447","y":2020,"url":"https://supreme.justia.com/cases/federal/us/561/447/","sc":1,"op":1,"by":{"2":"23"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"op":2,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"op":2,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"op":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Northwest Airlines, Inc. v. County of Kent","cite":"510 U.S. 355","y":1994,"id":"1993/92-97","sc":1,"sum":"Respondents, the owner and operators of Michigan's Kent County International Airport (collectively, the Airport), collect rent and fees from three groups of Airport users: commercial airlines, including petitioners (Airlines); general aviation; and concessionaires such as car rental agencies and gift shops. The Airport allocates its air-operations costs---e. g., maintaining runways-to the Airlines and general …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Rapoport v. SEC","cite":"682 F.3d 98","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/682/98/","by":{"2":"20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"1, 3-6, 8, 11, 13, 15, 16, 21"}},{"t":"usc","label":"29 U.S.C. § 654","url":"https://www.law.cornell.edu/uscode/text/29/654","stext":{"head":"§654. Duties of employers and employees","paras":[[0,"(a) Each employer—"],[1,"(1) shall furnish to each of his employees employment and a place of employment which are free from recognized hazards that are causing or are likely to cause death or serious physical harm to his employees;"],[1,"(2) shall comply with occupational safety and health standards promulgated under this chapter."],[0,"(b) Each employee shall comply with occupational safety and health standards and all rules, regulations, and orders issued pursuant to this chapter which are applicable to his own actions and conduct."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/654?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§654. Duties of employers and employees","tname":"Labor","by":{"2":"10"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)"],"by":{"2":"20"}},{"t":"usc","label":"28 U.S.C. § 594","url":"https://www.law.cornell.edu/uscode/text/28/594","subs":["(a)"],"by":{"2":"19"}}]};